#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Beta setup on Google Cloud (ADR-0053). Run from the repo root:
#   scripts/infra/gcp-setup.sh
# Non-secret answers are remembered in infra/gcp/.env.beta (git-ignored). Secret values are
# generated or pasted here and go straight into Secret Manager; they never touch a file.

TOTAL_STAGES=12
ENV_FILE="infra/gcp/.env.beta"
REGION="europe-west4"
SQL_INSTANCE_NAME="steuereule-beta"
KEYSTORE_SQL_INSTANCE_NAME="steuereule-beta-keystore"
TOFU_DIR="infra/gcp"

TOFU="$(command -v tofu || command -v terraform || true)"

secret_has_value() {
  [[ -n "$(gcloud secrets versions list "$1" --project "$GCP_PROJECT_ID" --filter=state=enabled --limit=1 --format='value(name)' 2>/dev/null)" ]]
}

put_secret() {
  local name="$1" value="$2"
  printf '%s' "$value" | gcloud secrets versions add "$name" --project "$GCP_PROJECT_ID" --data-file=- >/dev/null
  printf '  %s✓ stored%s %s in Secret Manager\n' "$GREEN" "$RESET" "$name"
}

ensure_generated_secret() {
  local name="$1" value="$2"
  if secret_has_value "$name"; then
    note "$name already has a value, left unchanged."
  else
    put_secret "$name" "$value"
  fi
}

tofu_output() { "$TOFU" -chdir="$TOFU_DIR" output -raw "$1"; }

banner "SteuerEule Beta auf Google Cloud einrichten"

stage "Werkzeuge und Anmeldung"
for tool in gcloud gh openssl curl; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool fehlt — bitte installieren und neu starten."; exit 1; }
done
[[ -n "$TOFU" ]] || { warn "OpenTofu (tofu) oder Terraform fehlt — 'brew install opentofu'."; exit 1; }
say "Benutzt: $TOFU"
gh auth status >/dev/null 2>&1 || { warn "gh ist nicht angemeldet — 'gh auth login' ausführen."; exit 1; }
say "Gleich öffnet sich zweimal der Browser für die Google-Anmeldung:"
step "einmal für die gcloud-CLI, einmal für OpenTofu (Application Default Credentials)."
pause "Bereit?"
gcloud auth login --quiet
gcloud auth application-default login --quiet

stage "Projekt und Abrechnung"
say "Das Startguthaben (300 \$ für 90 Tage) bekommst du beim Anlegen des Rechnungskontos."
open_url "https://console.cloud.google.com/billing"
step "Falls noch kein Rechnungskonto existiert: 'Konto erstellen' bzw. 'Kostenlos testen', Karte hinterlegen."
pause "Rechnungskonto vorhanden? Enter"
gcloud billing accounts list --format='table(name.basename():label=ID,displayName,open)'
ask BILLING_ACCOUNT_ID "ID des Rechnungskontos (Form 000000-000000-000000):"
ask GCP_PROJECT_ID "Projekt-ID (klein, z. B. steuereule-beta-1234; global eindeutig):"
write_env BILLING_ACCOUNT_ID "$BILLING_ACCOUNT_ID"
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
if gcloud projects describe "$GCP_PROJECT_ID" >/dev/null 2>&1; then
  note "Projekt $GCP_PROJECT_ID existiert bereits."
elif confirm "Projekt $GCP_PROJECT_ID jetzt anlegen?"; then
  gcloud projects create "$GCP_PROJECT_ID" --name "SteuerEule Beta"
else
  warn "Ohne Projekt geht es nicht weiter."; exit 1
fi
gcloud billing projects link "$GCP_PROJECT_ID" --billing-account "$BILLING_ACCOUNT_ID" >/dev/null
gcloud config set project "$GCP_PROJECT_ID" >/dev/null
gcloud auth application-default set-quota-project "$GCP_PROJECT_ID" >/dev/null 2>&1 || true
say "Projekt ist mit dem Rechnungskonto verknüpft."

stage "Speicher für den OpenTofu-State"
STATE_BUCKET="${GCP_PROJECT_ID}-tfstate"
gcloud services enable storage.googleapis.com --project "$GCP_PROJECT_ID"
if gcloud storage buckets describe "gs://$STATE_BUCKET" >/dev/null 2>&1; then
  note "Bucket gs://$STATE_BUCKET existiert bereits."
else
  gcloud storage buckets create "gs://$STATE_BUCKET" --project "$GCP_PROJECT_ID" --location "$REGION" \
    --uniform-bucket-level-access --public-access-prevention
  gcloud storage buckets update "gs://$STATE_BUCKET" --versioning
fi
write_env STATE_BUCKET "$STATE_BUCKET"

stage "Infrastruktur anlegen (OpenTofu)"
say "Legt an: Cloud SQL (Postgres 16), Artifact Registry, leere Secrets, Service-Accounts,"
say "GitHub-Zugang per Workload Identity und einen Budget-Alarm bei 20 € im Monat."
"$TOFU" -chdir="$TOFU_DIR" init -input=false -reconfigure -backend-config="bucket=$STATE_BUCKET" >/dev/null
TOFU_VARS=(-var "project_id=$GCP_PROJECT_ID" -var "billing_account_id=$BILLING_ACCOUNT_ID" -var "region=$REGION")
"$TOFU" -chdir="$TOFU_DIR" plan -input=false "${TOFU_VARS[@]}" -out=beta.tfplan
warn "Cloud SQL kostet ab jetzt ca. 10–12 € im Monat (in der Testphase vom Guthaben)."
if confirm "Plan anwenden?"; then
  "$TOFU" -chdir="$TOFU_DIR" apply -input=false beta.tfplan
  rm -f "$TOFU_DIR/beta.tfplan"
else
  warn "Abgebrochen, nichts angelegt."; exit 1
fi
SQL_CONNECTION="$(tofu_output sql_connection_name)"
KEYSTORE_SQL_CONNECTION="$(tofu_output keystore_sql_connection_name)"

stage "Domain und Absender"
say "Web läuft unter www.<domain>, die API unter api.<domain> (ADR-0053: gleiche Site für Cookies)."
ask APP_DOMAIN "Deine Domain ohne www (z. B. steuereule.de):"
ask EMAIL_FROM "Absender für Bestätigungsmails (z. B. noreply@$APP_DOMAIN):"
write_env APP_DOMAIN "$APP_DOMAIN"
write_env EMAIL_FROM "$EMAIL_FROM"

stage "App-Secrets erzeugen"
say "Werden lokal mit openssl erzeugt und direkt in Secret Manager geschrieben."
warn "Vorhandene Werte bleiben unangetastet — ein neuer PRISMA_FIELD_ENCRYPTION_KEY würde gespeicherte Daten unlesbar machen."
ensure_generated_secret GUEST_SESSION_SECRET "$(openssl rand -base64 48)"
ensure_generated_secret BETTER_AUTH_SECRET "$(openssl rand -base64 48)"
ensure_generated_secret PRISMA_FIELD_ENCRYPTION_KEY "k1.aesgcm256.$(openssl rand -base64 32)"
ensure_generated_secret KEYSTORE_MASTER_KEY "$(openssl rand -base64 48)"
pause

stage "Datenbank-Benutzer"
if secret_has_value DATABASE_URL; then
  note "DATABASE_URL ist bereits gesetzt, Benutzer bleibt unverändert."
else
  DB_PASSWORD="$(openssl rand -hex 24)"
  gcloud sql users create steuereule --instance "$SQL_INSTANCE_NAME" --project "$GCP_PROJECT_ID" --password "$DB_PASSWORD" >/dev/null
  put_secret DATABASE_URL "postgresql://steuereule:${DB_PASSWORD}@localhost/steuereule?host=/cloudsql/${SQL_CONNECTION}&connection_limit=5"
  unset DB_PASSWORD
fi
# Keystore (ADR-0059): own instance, own user, own password — never the tax-data credentials.
if secret_has_value KEYSTORE_DATABASE_URL; then
  note "KEYSTORE_DATABASE_URL ist bereits gesetzt, Benutzer bleibt unverändert."
else
  KEYSTORE_DB_PASSWORD="$(openssl rand -hex 24)"
  gcloud sql users create steuereule_keystore --instance "$KEYSTORE_SQL_INSTANCE_NAME" --project "$GCP_PROJECT_ID" --password "$KEYSTORE_DB_PASSWORD" >/dev/null
  put_secret KEYSTORE_DATABASE_URL "postgresql://steuereule_keystore:${KEYSTORE_DB_PASSWORD}@localhost/steuereule_keystore?host=/cloudsql/${KEYSTORE_SQL_CONNECTION}&connection_limit=2"
  unset KEYSTORE_DB_PASSWORD
fi
pause

stage "Brevo (Bestätigungsmails)"
open_url "https://app.brevo.com"
step "Domain $APP_DOMAIN als Absender-Domain authentifizieren; Brevo zeigt dir die DNS-Einträge dafür."
step "Unter den SMTP-/API-Einstellungen einen API-Schlüssel erzeugen und kopieren."
if secret_has_value BREVO_API_KEY && ! confirm "BREVO_API_KEY ist schon gesetzt. Ersetzen?"; then
  note "BREVO_API_KEY unverändert."
else
  ask_secret BREVO_KEY_INPUT "API-Schlüssel einfügen:"
  [[ -n "$BREVO_KEY_INPUT" ]] || { warn "Ohne Brevo-Schlüssel startet die API in Produktion nicht."; exit 1; }
  put_secret BREVO_API_KEY "$BREVO_KEY_INPUT"
  unset BREVO_KEY_INPUT
fi

stage "Optional: Google-Login und Stripe"
if confirm "Google-Login (OAuth) jetzt einrichten?"; then
  open_url "https://console.cloud.google.com/apis/credentials?project=$GCP_PROJECT_ID"
  step "OAuth-Client-ID vom Typ 'Webanwendung' anlegen."
  step "Autorisierte Weiterleitungs-URI: https://api.$APP_DOMAIN/api/auth/callback/google"
  ask GOOGLE_ID_INPUT "Client-ID einfügen:"
  ask_secret GOOGLE_SECRET_INPUT "Clientschlüssel einfügen:"
  put_secret GOOGLE_CLIENT_ID "$GOOGLE_ID_INPUT"
  put_secret GOOGLE_CLIENT_SECRET "$GOOGLE_SECRET_INPUT"
  unset GOOGLE_ID_INPUT GOOGLE_SECRET_INPUT
else
  note "Übersprungen — Google-Login bleibt aus, bis die Secrets gesetzt sind."
fi
if confirm "Stripe (Bezahlung beim Ausdruck) jetzt einrichten?"; then
  open_url "https://dashboard.stripe.com/apikeys"
  ask_secret STRIPE_KEY_INPUT "Secret Key einfügen (sk_test_… für die Beta):"
  step "Webhook-Endpunkt anlegen: https://api.$APP_DOMAIN/v1/zahlung/stripe/webhook"
  ask_secret STRIPE_WEBHOOK_INPUT "Signing Secret des Webhooks einfügen (whsec_…):"
  put_secret STRIPE_SECRET_KEY "$STRIPE_KEY_INPUT"
  put_secret STRIPE_WEBHOOK_SECRET "$STRIPE_WEBHOOK_INPUT"
  unset STRIPE_KEY_INPUT STRIPE_WEBHOOK_INPUT
else
  note "Übersprungen — der Ausdruck meldet 'Zahlung nicht eingerichtet'."
fi

stage "GitHub-Variablen für den Deploy"
set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
set_var GCP_REGION "$REGION"
set_var GCP_WIF_PROVIDER "$(tofu_output workload_identity_provider)"
set_var GCP_DEPLOYER_SA "$(tofu_output deployer_service_account)"
set_var GCP_RUNTIME_SA "$(tofu_output api_runtime_service_account)"
set_var GCP_WEB_SA "$(tofu_output web_runtime_service_account)"
set_var GCP_SQL_INSTANCE "$SQL_CONNECTION"
set_var GCP_KEYSTORE_SQL_INSTANCE "$KEYSTORE_SQL_CONNECTION"
set_var APP_DOMAIN "$APP_DOMAIN"
set_var EMAIL_FROM "$EMAIL_FROM"
pause

stage "Erster Deploy"
say "Baut beide Images, migriert die Datenbank und rollt API und Web aus (ca. 10–15 Minuten)."
if confirm "Deploy-Workflow auf main starten?"; then
  gh workflow run deploy.yml --ref main
  sleep 5
  gh run watch "$(gh run list --workflow deploy.yml --limit 1 --json databaseId --jq '.[0].databaseId')" --exit-status \
    || { warn "Deploy fehlgeschlagen — Log: gh run view --log-failed"; exit 1; }
else
  SKIPPED+=("Deploy starten: gh workflow run deploy.yml --ref main")
fi

stage "Domain verknüpfen"
say "Google muss erst bestätigen, dass dir $APP_DOMAIN gehört (Search Console, einmalig)."
gcloud domains verify "$APP_DOMAIN" >/dev/null 2>&1 || true
step "Im geöffneten Search-Console-Fenster den TXT-Eintrag bei deinem Domain-Anbieter setzen und 'Bestätigen' klicken."
pause "Domain bestätigt? Enter"
for pair in "www:steuereule-web" "api:steuereule-api"; do
  host="${pair%%:*}.$APP_DOMAIN"; service="${pair#*:}"
  if gcloud beta run domain-mappings describe --domain "$host" --region "$REGION" >/dev/null 2>&1; then
    note "$host ist bereits verknüpft."
  else
    gcloud beta run domain-mappings create --service "$service" --domain "$host" --region "$REGION"
  fi
done
say "Diese DNS-Einträge bei deinem Domain-Anbieter setzen:"
for host in "www.$APP_DOMAIN" "api.$APP_DOMAIN"; do
  gcloud beta run domain-mappings describe --domain "$host" --region "$REGION" \
    --format="table[box](status.resourceRecords.name,status.resourceRecords.type,status.resourceRecords.rrdata)"
done
note "Das TLS-Zertifikat stellt Google selbst aus, sobald die Einträge sichtbar sind (bis ca. 1 Stunde)."
pause "Einträge gesetzt? Enter"

stage "Prüfen"
say "Warte auf https://api.$APP_DOMAIN …"
if curl -fsS --retry 30 --retry-delay 20 --retry-all-errors "https://api.$APP_DOMAIN/v1/health/ready"; then
  printf '\n'
  say "API antwortet. Web: https://www.$APP_DOMAIN"
  open_url "https://www.$APP_DOMAIN"
else
  SKIPPED+=("https://api.$APP_DOMAIN antwortet noch nicht — DNS/Zertifikat später erneut prüfen")
fi
note "TRUSTED_PROXIES: in den Cloud-Run-Logs prüfen, welche Peer-Adresse die API sieht (ADR-0053)."

finish
